steps:
set -eu
pgroot=$(cat /tmp/showstake-pg-bootstrap-path)
pgbin="$pgroot/extracted/usr/lib/postgresql/18/bin"
mkdir "$pgroot/socket"
"$pgbin/initdb" -D "$pgroot/data" -L "$pgroot/extracted/usr/share/postgresql/18" --auth-local=trust --auth-host=reject --no-locale > "$pgroot/initdb.log"
"$pgbin/pg_ctl" -D "$pgroot/data" -l "$pgroot/server.log" -o "-k $pgroot/socket -c listen_addresses='' -p 55439" -w start
trap '"$pgbin/pg_ctl" -D "$pgroot/data" -m fast -w stop' EXIT
psql -h "$pgroot/socket" -p 55439 -d postgres -v ON_ERROR_STOP=1 -c 'CREATE DATABASE showstake_disposable;'
psql -h "$pgroot/socket" -p 55439 -d showstake_disposable -v ON_ERROR_STOP=1 -f '/mnt/d/Belajar/Hackacton/Hackacton yang masih jalan/ShowStake/docs/planning/showstake-v2/schema.sql'
psql -h "$pgroot/socket" -p 55439 -d showstake_disposable -v ON_ERROR_STOP=1 <<'SQL'
DO $$ BEGIN
 IF (SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE') <> 22 THEN RAISE EXCEPTION 'table count mismatch'; END IF;
 BEGIN PERFORM '-1'::atomic_amount; RAISE EXCEPTION 'negative accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
 BEGIN PERFORM '1.5'::atomic_amount; RAISE EXCEPTION 'fraction accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
 BEGIN PERFORM '340282366920938463463374607431768211456'::atomic_amount; RAISE EXCEPTION 'overflow accepted'; EXCEPTION WHEN check_violation THEN NULL; END;
 PERFORM '340282366920938463463374607431768211455'::atomic_amount;
 BEGIN INSERT INTO auth_identities VALUES ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000001','fixture','fixture',now()); RAISE EXCEPTION 'orphan accepted'; EXCEPTION WHEN foreign_key_violation THEN NULL; END;
END $$;
BEGIN;
INSERT INTO app_users(id) VALUES ('00000000-0000-0000-0000-000000000001');
ROLLBACK;
DO $$ BEGIN IF EXISTS (SELECT FROM app_users) THEN RAISE EXCEPTION 'rollback failed'; END IF; END $$;
SELECT 'PASS_LOCAL: DDL apply, 22 tables, atomic bounds, FK rejection, rollback' AS result;
SQL
